/**
 * EXAMPLE DATA. These twelve heroes are invented for the Hero Ops Console demo.
 * They are not real people, and nothing here is loaded from a backend.
 */
export const EXAMPLE_ROSTER: readonly Hero[] = [
  { id: 'HRO-0007', name: 'Silverwing', alias: 'Ada Voss', powerClass: 'Aerial', powerIndex: 88, status: 'Active', clearanceTier: 4, missionCount: 64, successRate: 92, notes: 'Precision flyer. Excels at extraction and high-altitude recon. Pairs well with ground-anchor heroes on breach ops.' },
