import { Directive, input } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';
import { HlmCardConfig, injectHlmCardConfig } from './hlm-card.token';
@Directive({
  selector: '[hlmCard],hlm-card',
  host: {
    'data-slot': 'card',
    '[attr.data-size]': 'size()',
  },
})
export class HlmCard {
  private readonly _defaultConfig = injectHlmCardConfig();
  public readonly size = input<HlmCardConfig['size']>(this._defaultConfig.size);
  constructor() {
    classes(
      () =>
        'ring-foreground/10 bg-card text-card-foreground gap-(--card-spacing) overflow-hidden rounded-xl py-(--card-spacing) text-sm shadow-xs ring-1 [--card-spacing:--spacing(6)] has-[>img:first-child]:pt-0 data-[size=sm]:[--card-spacing:--spacing(4)] *:[img:first-child]:rounded-t-xl *:[img:last-child]:rounded-b-xl group/card flex flex-col',
    );
  }
}
import { Directive } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';
@Directive({
  selector: '[hlmCardHeader],hlm-card-header',
  host: { 'data-slot': 'card-header' },
})
export class HlmCardHeader {
  constructor() {
    classes(
      () =>
        'gap-1 rounded-t-xl px-(--card-spacing) [.border-b]:pb-(--card-spacing) group/card-header @container/card-header grid auto-rows-min items-start has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto]',
    );
  }
}
import { Directive, input } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';
export type HlmCardTitleEmphasis = 'default' | 'stat' | 'title';
@Directive({
  selector: '[hlmCardTitle]',
  host: { 'data-slot': 'card-title' },
})
export class HlmCardTitle {
  /** 'stat' renders the headline-number treatment dashboard stat tiles need. */
  readonly emphasis = input<HlmCardTitleEmphasis>('default');
  constructor() {
    classes(() =>
      this.emphasis() === 'stat'
        ? 'text-3xl leading-tight font-bold group-data-[size=sm]/card:text-2xl'
        : this.emphasis() === 'title'
          ? 'text-2xl leading-tight font-bold'
          : 'text-base leading-normal font-medium group-data-[size=sm]/card:text-sm',
    );
  }
}
import { Directive } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';
@Directive({
  selector: '[hlmCardContent]',
  host: { 'data-slot': 'card-content' },
})
export class HlmCardContent {
  constructor() {
    classes(() => 'px-(--card-spacing)');
  }
}
import { Directive } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';
@Directive({
  selector: '[hlmCardDescription]',
  host: { 'data-slot': 'card-description' },
})
export class HlmCardDescription {
  constructor() {
    classes(() => 'text-muted-foreground text-sm');
  }
}
import { Directive } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';
@Directive({
  selector: '[hlmCardFooter],hlm-card-footer',
  host: { 'data-slot': 'card-footer' },
})
export class HlmCardFooter {
  constructor() {
    classes(
      () => 'rounded-b-xl px-(--card-spacing) [.border-t]:pt-(--card-spacing) flex items-center',
    );
  }
}
import { Directive } from '@angular/core';
import { classes } from '@spartan-ng/helm/utils';
@Directive({
  selector: '[hlmCardAction]',
  host: { 'data-slot': 'card-action' },
})
export class HlmCardAction {
  constructor() {
    classes(() => 'col-start-2 row-span-2 row-start-1 self-start justify-self-end');
  }
}
